                                                              = new VarTypeResolver() {

    @Override
    public TypeConstant resolve(Frame frame, int nTargetReg, int iAuxId) {
        TypeConstant typeArray;
        if (nTargetReg >= 0) {
            VarInfo infoArray = frame.getVarInfo(nTargetReg);
            typeArray = infoArray.getType();
        } else {

            typeArray = frame.getLocalType(nTargetReg, null);
        }

        TypeConstant typeEl = typeArray.getParamType(typeArray.isTuple() ? iAuxId : 0);
        return typeEl.resolveGenerics(frame.poolContext(), frame.getGenericsResolver(false));
    }
}

                                                         = new VarTypeResolver() {

    @Override
    public TypeConstant resolve(Frame frame, int nTargetReg, int iPropId) {
        ConstantPool pool = frame.poolContext();

        PropertyConstant constProperty = frame.getConstant(iPropId, PropertyConstant.class);
        TypeConstant     typeTarget    = nTargetReg >= 0
            ? frame.f_ahVar[nTargetReg].getType()
            : frame.getLocalType(nTargetReg, null);

        boolean fFormal = constProperty.isFormalType();
        if (fFormal && constProperty.getFormat() == Constant.Format.Property) {
            return typeTarget.resolveFormalType(constProperty).getType();
        }
        TypeConstant typeResolved = constProperty.getType().
            resolveGenerics(pool, frame.getGenericsResolver(false));
        return fFormal
            ? typeResolved.getType()
            : typeResolved;
    }
}

                                                       = new VarTypeResolver() {

    @Override
    public TypeConstant resolve(Frame frame, int nTargetReg, int iAuxId) {
        ConstantPool pool = frame.poolContext();

        MethodConstant idMethod = nTargetReg < 0
            ? frame.getConstant(nTargetReg, MethodConstant.class)
            : ((FunctionHandle) frame.f_ahVar[nTargetReg]).getMethodId();

        return frame.resolveType(iAuxId >= 0
            ? idMethod.getRawReturns()[iAuxId]
            : pool.ensureTupleType(idMethod.getSignature().getRawReturns()));
    }
}

                                                    = new VarTypeResolver() {

    @Override
    public TypeConstant resolve(Frame frame, int nTargetReg, int iAuxId) {
        TypeConstant typeRef = frame.getVarInfo(nTargetReg).getType();
        return typeRef.resolveGenericType("Referent");
    }
}

                                      = new Op[] {
    new Op() {
        public int process(Frame frame, int iPC) {
            assert frame.f_ahVar.length == 1 && frame.f_iReturn == A_IGNORE;

            CompletableFuture cf = ((NativeFutureHandle) frame.f_ahVar[0]).f_future;

            return cf.isDone() ? R_RETURN : R_REPEAT;
        }
        public String toString() {
            return "WaitForIO";
        }
    }
}
